window.VOCAB_LWS_META = [{"batch":2,"added":"2026-11-07","lesson":1,"lesson_title":"Glück im Alltag","book":"Schritte plus Neu 5 · Lernwortschatz","pages":"LWS 171–175","tips":[{"text":"Das Wort *als* hat mehrere Bedeutungen. Schreiben Sie zu jeder Bedeutung einen Satz.","text_en":"La palabra *als* tiene varios significados. Escribe una frase para cada significado.","example":"Wann? Als ich drei Jahre alt war, bekam ich mein erstes Haustier.","answer":["Vergleich: Jan ist älter als Julian","Berufsbezeichnung: Er arbeitet als Arzt"],"note":"Tres significados: *als* = cuando (un hecho único en el pasado, verbo al final), *als* tras un comparativo = que, *als* + profesión o papel = como. Para algo que pasaba una y otra vez en el pasado, usa *wenn*, no *als*."}],"count":78},{"batch":3,"added":"2026-11-07","lesson":2,"lesson_title":"Unterhaltung","book":"Schritte plus Neu 5 · Lernwortschatz","pages":"LWS 175–179","tips":[{"text":"Schreiben Sie eine kleine Geschichte mit den Wörtern aus der Lektion.","text_en":"Escribe una historia corta con las palabras de la lección.","example":"Meine Geschichte handelt von einem unglaublichen Abenteuer: Ich begegnete in einer grossen Stadt dem Star aus meiner Lieblingsserie. Unglaublich! Ich war optimistisch, dass …","answer":["… ich ein Foto mit ihm machen kann. Ich hatte zwar nicht den Mut, ihn anzusprechen, aber dann kam die grosse Überraschung: Er fragte mich, wo der Bahnhof ist!"],"note":"Una respuesta modelo; la tuya puede ser muy distinta. En español: «… que pude hacerme una foto con él. Es cierto que no tuve el valor de hablarle, pero entonces llegó la gran sorpresa: ¡me preguntó dónde estaba la estación!» Reutiliza *zwar … aber*, *der Mut* y *die Überraschung* de la Lección 1."}],"count":66},{"batch":4,"added":"2026-11-07","lesson":3,"lesson_title":"Gesund bleiben","book":"Schritte plus Neu 5 · Lernwortschatz","pages":"LWS 179–183","tips":[{"text":"Lernen Sie typische Wendungen zusammen.","text_en":"Aprende juntas las expresiones típicas.","example":"den Blutdruck messen, Blut abnehmen, das Gewicht prüfen, den Bauch …","answer":["den Bauch untersuchen","jemanden impfen","Medikamente verschreiben","jemanden krankschreiben","ein Gespräch führen","einen Termin vereinbaren","Sport treiben","auf Schokolade verzichten"],"note":"*den Bauch untersuchen* completa la lista del libro (examinar el abdomen). Las demás son combinaciones de palabras de esta lección que conviene aprender como una unidad: vacunarse, recetar medicamentos, dar la baja a alguien, mantener una conversación, pedir una cita, hacer deporte, renunciar al chocolate."}],"count":68},{"batch":1,"added":"2026-11-06","lesson":4,"lesson_title":"Sprachen","book":"Schritte plus Neu 5 · Lernwortschatz","pages":"LWS 184–187","tips":[{"text":"Im Deutschen enden viele Sprachen auf «-isch». Schreiben Sie.","text_en":"En alemán, muchos idiomas terminan en -isch. Escribe algunos.","example":"Griechisch, Französisch, …","answer":["Englisch","Spanisch","Italienisch","Portugiesisch","Russisch","Polnisch","Türkisch","Arabisch","Chinesisch","Japanisch","Ungarisch","Albanisch"],"note":"Los nombres de idiomas son neutros y normalmente no llevan artículo: *Ich lerne Spanisch.* No todos los idiomas terminan en *-isch*: *Deutsch*, *Hindi* y *Swahili* no."}],"count":60},{"batch":5,"added":"2026-11-09","lesson":5,"lesson_title":"Eine Arbeit finden","book":"Schritte plus Neu 5 · Lernwortschatz","pages":"LWS 188–191","tips":[{"text":"Notieren Sie einen Beruf. Bilden Sie mit seinen Buchstaben einen Satz.","text_en":"Escribe una profesión. Forma una frase con sus letras.","example":"Maler: *M*ein *A*rzt *l*iest *e*inen *R*eiseführer.","answer":["Arzt: Anna ruft zwei Taxis","Lehrer: Lara erklärt heute Ronja einen Roman"],"note":"Cada palabra empieza con la siguiente letra de la profesión. Vale cualquier frase que funcione."}],"count":53},{"batch":6,"added":"2026-11-09","lesson":6,"lesson_title":"Dienstleistung","book":"Schritte plus Neu 5 · Lernwortschatz","pages":"LWS 191–195","tips":[{"text":"Bilden Sie mit den Buchstaben von einem langen Wort neue Wörter.","text_en":"Forma palabras nuevas con las letras de una palabra larga.","example":"Bedienungsanleitung: laut, Dienstag, Tal, …","answer":["Bad","Geld","Insel","Nadel","Lied","Sieg","Tanne","Leben"],"note":"Usa cada letra de *Bedienungsanleitung* como máximo tantas veces como aparece en la palabra."}],"count":66},{"batch":7,"added":"2026-11-09","lesson":7,"lesson_title":"Rund ums Wohnen","book":"Schritte plus Neu 5 · Lernwortschatz","pages":"LWS 196–200","tips":[{"text":"Leiten Sie unbekannte Wörter von bekannten Wörtern ab.","text_en":"Deduce palabras desconocidas a partir de palabras que conoces.","example":"unaufmerksam = nicht aufmerksam","answer":["unverständlich = nicht verständlich","ungemütlich = nicht gemütlich","friedlich = ohne Streit, voller Frieden","der Stadtrand = der Rand der Stadt","das Fernsehverbot = das Verbot, fernzusehen"],"note":"*un-* convierte un adjetivo en su contrario; un sustantivo compuesto se explica por su última parte."}],"count":67}];
